#include <stdio.h>
void counter(void) {
    static int count = 1;
    printf("%d ", count);
    count++;
}
int main(void) {
    counter();
    counter();
    counter();
    printf("\n");
    return 0;
}

#include <stdio.h>
void countdown(int n) {
    if (n <= 0) return;
    printf("%d ", n);
    countdown(n - 1);
}
int main(void) {
    countdown(3);
    printf("\n");
    return 0;
}

#include <stdio.h>
int square(int x) {
    return x * x;
}
int main(void) {
    double val = 4.8;
    printf("%d\n", square(val));
    return 0;
}

#include <stdio.h>
void print_back(int n) {
    if (n == 0) return;
    print_back(n - 1);
    printf("%d ", n);
}
int main(void) {
    print_back(3);
    printf("\n");
    return 0;
}

