#include <stdio.h>
int power(int base, int exp) {
    int result = 1;
    for (int i = 0; i < exp; i++) {
        result *= base;
    }
    return result;
}
int main(void) {
    printf("Result: %d\n", power(2, 4));
    return 0;
}

